actions.script:
canEdit = ec.user.hasPermission('MONITOR_EVAL')
const count = (n, c) => ec.entity.find(n).condition(c).disableAuthz().count()
datasetRows = Array.from(datasetList).map(d => Object.assign(d.getMap(), {
    itemCount: Array.from(ec.entity.find('moqui.agent.AgentDatasetItem').condition({datasetId: d.datasetId}).disableAuthz().list()).filter(i => i.thruVersion == null).length,
    experimentCount: count('moqui.agent.AgentExperiment', {datasetId: d.datasetId})}))
agentOptions = Array.from(ec.entity.find('moqui.agent.AgentDefinition').disableAuthz().list()).map(a => ({value: a.agentId, label: a.agentName || a.agentId}))
